ND), 1, 1)::int,
                    CASE WHEN us_market_slug IS NOT NULL THEN 4 ELSE 0 END)
      WHEN us_market_slug IS NOT NULL THEN 4
      ELSE 0
    END AS reach
          FROM ext_candidate_outcomes
         WHERE cycle_at >= to_timestamp(1791622474.8284767) AND cycle_at < to_timestamp(1791626075.8284767)
           AND provider_event_id IS NOT NULL)
    SELECT sport_key, provider_event_id, max(family) AS family,
           count(*) AS rows, max(reach) AS reach,
           (array_agg(stage_d ORDER BY reach DESC, cycle_at DESC, id DESC))[1] AS stage,
           (array_agg(outcome ORDER BY reach DESC, cycle_at DESC, id DESC))[1] AS outcome,
           (array_agg(first_refusal ORDER BY reach DESC, cycle_at DESC, id DESC))[1] AS first_refusal,
           (array_agg(codes ORDER BY reach DESC, cycle_at DESC, id DESC))[1] AS codes,
           (array_agg(us_market_slug ORDER BY reach DESC, cycle_at DESC, id DESC))[1] AS us_market_slug,
           array_remove(array_agg(DISTINCT us_market_slug), NULL) AS slugs,
           max(home) AS home, max(away) AS away,
           max(commence_time) AS commence_time,
           extract(epoch FROM max(cycle_at))::float8 AS last_cycle_at
      FROM r GROUP BY sport_key, provider_event_id
     ORDER BY sport_key, provider_event_id
     LIMIT 20000
),
vl AS (
  SELECT id, event_key, us_market_slug, record_purpose, refusals, admissible
    FROM external_valuations
   WHERE decided_at >= to_timestamp(1791622474.8284767) AND decided_at < to_timestamp(1791626075.8284767)
     AND record_purpose IN ('ENTRY_DECISION', 'CALIBRATION_ONLY')
     AND (event_key = ANY(coalesce((SELECT array_agg(provider_event_id::text) FROM ev), ARRAY[]::text[]))
          OR us_market_slug = ANY(coalesce((SELECT array_agg(DISTINCT s) FROM ev, unnest(ev.slugs) s), ARRAY[]::text[])))
),
dc AS (
  SELECT valuation_id, verdict, refusal, refusals, strategy
    FROM paper_decisions
   WHERE valuation_id = ANY(coalesce((SELECT array_agg(id::bigint) FROM vl), ARRAY[]::bigint[]))
     AND decided_at >= to_timestamp(1791622474.8284767) - interval '1 day'
)
SELECT json_build_object('w', 'A', 'ev', to_jsonb(ev),
  'vals', (SELECT coalesce(jsonb_agg(to_jsonb(vl)), '[]'::jsonb) FROM vl
            WHERE vl.event_key = ev.provider_event_id::text
               OR vl.us_market_slug = ANY(ev.slugs) OR vl.us_market_slug = ev.us_market_slug),
  'decs', (SELECT coalesce(jsonb_agg(to_jsonb(dc)), '[]'::jsonb) FROM dc
            WHERE dc.valuation_id IN (SELECT vl.id FROM vl
                  WHERE vl.event_key = ev.provider_event_id::text
                     OR vl.us_market_slug = ANY(ev.slugs) OR vl.us_market_slug = ev.us_market_slug)))::text AS j
  FROM ev ORDER BY ev.sport_key, ev.provider_event_id;

